default_theme:
$__theme: m.define-light-theme((
  color: (
    primary: m.define-palette(m.$indigo-palette),
    accent: m.define-palette(m.$pink-palette, A200, A100, A400),
    warn: m.define-palette(m.$red-palette),
  ),
  typography: m.define-typography-config(),
  density: 0,
));

